package br.com.marquesautodetail.api.favorito; import br.com.marquesautodetail.api.empresa.Empresa; import br.com.marquesautodetail.api.usuario.Usuario; import jakarta.persistence.*;
@Entity @Table(name="favoritos", uniqueConstraints=@UniqueConstraint(columnNames={"cliente_id","empresa_id"})) public class Favorito{ @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="cliente_id") private Usuario cliente; @ManyToOne @JoinColumn(name="empresa_id") private Empresa empresa; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Usuario getCliente(){return cliente;} public void setCliente(Usuario cliente){this.cliente=cliente;} public Empresa getEmpresa(){return empresa;} public void setEmpresa(Empresa empresa){this.empresa=empresa;} }
